function findMaxMin(a, b, c)
{
    let max, min;

    if (a > b) {
        if (a > c) {
            max = a;
            min = (b < c) ? b : c;
        } else {
            max = c;
            min = b;
        }
    } else {
        if (b > c) {
            max = b;
            min = (a < c) ? a : c;
        } else {
            max = c;
            min = a;
        }
    }

    return { max, min };
}

