function areIntervalsIntersecting(a, b, c, d)
{
    if ((c <= a && b <= d) ||
        (a <= c && c <= b && b <= d) ||
        (a <= c && d <= b) ||
        (c <= a && a <= d && d <= b)) {
        return 1; // Yes
    } else {
        return 0; // No
    }
}

