function count_coloring_methods(n, m)
{
    const MOD = 1000003;
    let f = new Array(1111); // Array to store results
    if (n === 1) return m;
    if (n === 2) return (m * (m - 1)) % MOD;

    // Initialize the first three elements
    f[1] = m;
    f[2] = (m * (m - 1)) % MOD;
    // Formula derived from the given gold.c code
    f[3] = (f[2] * (m - 2)) % MOD;

    for (let i = 4; i <= n; i++) {
        f[i] = ((f[i - 1] * (m - 2)) % MOD +
                (f[i - 2] * (m - 1)) % MOD) % MOD;
    }
    return f[n];
}

