const countValidCoinTossSequences = (n) =>
{
    const a = Array.from({ length: n + 1 }, () => Array(2).fill(0));
    a[1][0] = a[1][1] = 1;

    for (let i = 2; i <= n; i++) {
        a[i][0] = a[i - 1][1] + a[i - 1][0];
        a[i][1] = a[i - 1][0];
    }

    return a[n][0] + a[n][1];
};

