function newModuloFactorial(n, p)
{
    const pj = new Array(p).fill(1);
    for (let i = 2; i < p; i++) pj[i] = (i * pj[i - 1]) % p;

    let ans = 1;
    while (n > 0) {
        ans = (ans * pj[n % p]) % p;
        ans = ((n / p) & 1) ? p - ans : ans;
        n = Math.floor(n / p);
    }
    return ans;
}

