    dp[0][0] = f[0] = jc[0] = 1;

    for (let i = 1; i <= n; i++) {
        jc[i] = (jc[i - 1] * i) % P;
    }

    for (let i = 1; i <= n; i++) {
        f[i] = jc[i];
        for (let j = 1; j < i; j++) {
