        }
    }

    for (let i = 1; i <= n; i++) {
        for (let j = 0; j < i; j++) {
            for (let kk = 1; kk <= n; kk++) {
                dp[i][kk] = (dp[i][kk] + dp[j][kk - 1] * f[i - j]) % P;
            }
        }
    }

    let m = 0;
    for (let i = 1; i < n; i++) {
        if (q[i - 1] > q[i]) {
            m = i;
            break;
        }
    }

    let ans = 0;
    if (m === n || m === 0) {
        for (let i = k; i <= n; i++) {
            ans = (ans + dp[n][i]) % P;
        }
    } else {
        for (let i = m + 1; i <= n; i++) {
            if (i !== m + 1 && (q[i - 2] > q[i - 1] || q[i - 1] < q[m - 1])) {
                break;
